#include <iostream>
template <typename T>
class MyClass {
public:
  T value;
  MyClass(T val) : value(val) {}
  static int static_counter;
};
template <typename T>
int MyClass<T>::static_counter = 0;
int main() {
  MyClass<int> obj1(10);
  MyClass<double> obj2(3.14);
  std::cout << obj1.value << " " << obj2.value << std::endl;
  std::cout << MyClass<int>::static_counter << std::endl; // Only instantiated once
  return 0;
}
